(()=>{const key='dat-portfolio:theme:v1';const buttons=[...document.querySelectorAll('[data-theme-choice]')];function apply(theme){document.documentElement.dataset.theme=theme;buttons.forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.themeChoice===theme)));}buttons.forEach(button=>button.addEventListener('click',()=>{const theme=button.dataset.themeChoice;apply(theme);try{localStorage.setItem(key,theme);}catch{}}));window.addEventListener('storage',e=>{if(e.key===key)apply(e.newValue==='soft-pink'?'soft-pink':'original');});apply(document.documentElement.dataset.theme==='soft-pink'?'soft-pink':'original');})();
